<script>
let cart=JSON.parse(sessionStorage.getItem("timedCart")||"[]");
function updateCount(){document.getElementById("cartCount").textContent=cart.reduce((sum,item)=>sum+item.quantity,0);}
function addItem(id,name,price){let found=cart.find(item=>item.id===id);if(found)found.quantity++;else cart.push({id:id,name:name,price:price,quantity:1});sessionStorage.setItem("timedCart",JSON.stringify(cart));updateCount();alert(name+" added to cart!");}
updateCount();
</script></body></html>
